<script>
(()=>{const modules=[...document.querySelectorAll('.module')];const links=[...document.querySelectorAll('[data-module]')];const select=document.getElementById('mobileModule');function openModule(key){if(!document.getElementById('module-'+key))key='dashboard';modules.forEach(el=>el.classList.toggle('active',el.id==='module-'+key));links.forEach(el=>{el.classList.toggle('active',el.dataset.module===key);if(el.dataset.module===key)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current')});select.value=key;history.replaceState(null,'','#'+key);window.scrollTo({top:0,behavior:'instant'})}links.forEach(el=>el.addEventListener('click',e=>{e.preventDefault();openModule(el.dataset.module)}));document.querySelectorAll('[data-open]').forEach(el=>el.addEventListener('click',()=>openModule(el.dataset.open)));select.addEventListener('change',()=>openModule(select.value));openModule(location.hash.slice(1)||'dashboard')})();
</script></body></html>
